// Quick tools: requirements checklist, risk-tier self-check, compliance card.
// Plain JavaScript, no framework, no network requests: the data is in the
// page (generated by scripts/build_from_docx.py), so it also works offline.
(function () {
  "use strict";

  // ---------------------------------------------------------------- helpers
  var store = {            // localStorage that never throws (private mode, blocked storage)
    get: function (k) { try { return window.localStorage.getItem(k); } catch (e) { return null; } },
    set: function (k, v) { try { window.localStorage.setItem(k, v); } catch (e) { /* ignore */ } },
    del: function (k) { try { window.localStorage.removeItem(k); } catch (e) { /* ignore */ } }
  };

  function download(name, text, type) {
    var blob = new Blob([text], { type: type });
    var a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = name;
    document.body.appendChild(a);
    a.click();
    setTimeout(function () { URL.revokeObjectURL(a.href); a.remove(); }, 0);
  }

  function csvCell(s) {
    s = String(s == null ? "" : s);
    return /[",\n;]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
  }

  function data(root) {
    var el = root.querySelector("script[data-px-data]");
    try { return el ? JSON.parse(el.textContent) : null; } catch (e) { return null; }
  }

  function esc(s) {
    return String(s).replace(/[&<>"]/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c];
    });
  }

  // -------------------------------------------------------------- checklist
  function checklist(root) {
    var key = root.getAttribute("data-storage-key");
    var rows = Array.prototype.slice.call(root.querySelectorAll("tbody tr"));
    var filters = root.querySelectorAll("[data-filter]");
    var count = root.querySelector("[data-count]");
    var ticks = {};
    try { ticks = JSON.parse(store.get(key) || "{}") || {}; } catch (e) { ticks = {}; }

    rows.forEach(function (tr) {
      var box = tr.querySelector("input[type=checkbox]");
      box.checked = !!ticks[tr.dataset.id];
      tr.classList.toggle("is-done", box.checked);
      box.addEventListener("change", function () {
        if (box.checked) { ticks[tr.dataset.id] = true; } else { delete ticks[tr.dataset.id]; }
        tr.classList.toggle("is-done", box.checked);
        store.set(key, JSON.stringify(ticks));
        update();
      });
    });

    function value(name) {
      var el = root.querySelector('[data-filter="' + name + '"]');
      return el ? el.value.trim() : "";
    }

    function visibleRows() { return rows.filter(function (tr) { return !tr.hidden; }); }

    function update() {
      var role = value("role"), stage = value("stage"), binding = value("binding"),
          uc = value("uc"), q = value("q").toLowerCase();
      rows.forEach(function (tr) {
        var d = tr.dataset;
        var ucs = d.uc ? d.uc.split(" ") : [];            // empty = applies to all
        var show = (!role || d.role === role) && (!stage || d.stage === stage) &&
                   (!binding || d.binding === binding) &&
                   (!uc || ucs.length === 0 || ucs.indexOf(uc) !== -1) &&
                   (!q || tr.textContent.toLowerCase().indexOf(q) !== -1);
        tr.hidden = !show;
      });
      var vis = visibleRows();
      var done = vis.filter(function (tr) { return tr.querySelector("input").checked; }).length;
      count.textContent = vis.length + " of " + rows.length + " requirements shown · " +
                          done + " ticked";
    }

    Array.prototype.forEach.call(filters, function (f) {
      f.addEventListener(f.tagName === "SELECT" ? "change" : "input", update);
    });

    root.addEventListener("click", function (ev) {
      var btn = ev.target.closest("[data-action]");
      if (!btn) return;
      var action = btn.getAttribute("data-action");
      if (action === "csv") {
        var head = Array.prototype.map.call(root.querySelectorAll("thead th"),
                                            function (th) { return th.textContent.trim(); });
        var lines = [head.map(csvCell).join(",")];
        visibleRows().forEach(function (tr) {
          var cells = Array.prototype.map.call(tr.children, function (td, i) {
            return i === 0 ? (td.querySelector("input").checked ? "yes" : "no") : td.textContent.trim();
          });
          lines.push(cells.map(csvCell).join(","));
        });
        download("proteus-rai-checklist.csv", "﻿" + lines.join("\r\n"), "text/csv;charset=utf-8");
      } else if (action === "print") {
        window.print();
      } else if (action === "clear") {
        if (!window.confirm("Clear all ticks on this page?")) return;
        ticks = {};
        store.del(key);
        rows.forEach(function (tr) { tr.querySelector("input").checked = false; tr.classList.remove("is-done"); });
        update();
      }
    });

    // Deep links (#DC-01): reveal the row even if a filter would hide it.
    function showTarget() {
      var id = decodeURIComponent(location.hash.slice(1));
      var tr = id && document.getElementById(id);
      if (!tr || rows.indexOf(tr) === -1) return;
      Array.prototype.forEach.call(filters, function (f) { f.value = ""; });
      update();
      tr.classList.add("is-target");
      tr.scrollIntoView({ block: "center" });
    }
    window.addEventListener("hashchange", showTarget);
    update();
    showTarget();
  }

  // ------------------------------------------------------- risk self-check
  function riskcheck(root) {
    var cfg = data(root);
    if (!cfg) return;
    var order = ["low", "medium", "high"];
    var form = root.querySelector("form");
    var out = root.querySelector("[data-result]");

    function update() {
      var answered = 0, tier = "low", reasons = [];
      cfg.questions.forEach(function (q) {
        var sel = form.querySelector('input[name="' + q.id + '"]:checked');
        if (!sel) return;
        answered += 1;
        if (sel.value === "yes") {
          reasons.push(q.text);
          if (order.indexOf(q.if_yes) > order.indexOf(tier)) tier = q.if_yes;
        }
      });
      if (answered < cfg.questions.length) {
        out.hidden = false;
        out.className = "px-result";
        out.innerHTML = "<p>" + answered + " of " + cfg.questions.length +
                        " questions answered.</p>";
        return;
      }
      var t = cfg.tiers[tier] || {};
      var html = '<p class="px-result__tier">Suggested tier: <strong>' + tier.toUpperCase() +
                 "</strong></p>";
      if (t.description) html += "<p>" + esc(t.description) + "</p>";
      if (reasons.length) {
        html += "<p>Because you answered yes to:</p><ul>" +
                reasons.map(function (r) { return "<li>" + esc(r) + "</li>"; }).join("") + "</ul>";
      }
      if (t.triggers && t.triggers.length) {
        html += "<p>What this tier triggers <em>(draft)</em>:</p><ul>" +
                t.triggers.map(function (r) { return "<li>" + esc(r) + "</li>"; }).join("") + "</ul>";
      }
      html += '<p class="px-result__note">Indicative only: the responsible AI reviewer decides the tier.</p>';
      out.className = "px-result px-result--" + tier;
      out.innerHTML = html;
      out.hidden = false;
    }

    form.addEventListener("change", update);
    root.querySelector('[data-action="reset"]').addEventListener("click", function () {
      form.reset();
      out.hidden = true;
    });
  }

  // -------------------------------------------------------- compliance card
  function card(root) {
    var schema = data(root);
    if (!schema) return;
    var form = root.querySelector("form");
    var stageSel = form.querySelector("[data-stage-select]");
    var key = "proteus-rai-card:" + (root.getAttribute("data-version") || "");

    function showStage() {
      Array.prototype.forEach.call(root.querySelectorAll("[data-stage]"), function (s) {
        s.hidden = s.getAttribute("data-stage") !== stageSel.value;
      });
    }

    function collect() {
      var stage = stageSel.value;
      var out = {
        guideline_version: root.getAttribute("data-version") || "",
        item: {}, stage: stage, parameters: {}
      };
      Array.prototype.forEach.call(form.elements, function (el) {
        if (!el.name) return;
        var parts = el.name.split(".");
        if (parts[0] === "item") { out.item[parts[1]] = el.value; return; }
        if (parts.length !== 2) return;
        var section = el.closest("[data-stage]");
        if (section && section.getAttribute("data-stage") !== stage) return;
        out.parameters[parts[0]] = out.parameters[parts[0]] || {};
        out.parameters[parts[0]][parts[1]] = el.value;
      });
      return out;
    }

    function save() { store.set(key, JSON.stringify(collect())); }

    function restore() {
      var saved;
      try { saved = JSON.parse(store.get(key) || "null"); } catch (e) { saved = null; }
      if (!saved) return;
      Object.keys(saved.item || {}).forEach(function (k) {
        var el = form.elements["item." + k];
        if (el) el.value = saved.item[k];
      });
      if (saved.stage) stageSel.value = saved.stage;
      Object.keys(saved.parameters || {}).forEach(function (pid) {
        Object.keys(saved.parameters[pid]).forEach(function (f) {
          var el = form.elements[pid + "." + f];
          if (el) el.value = saved.parameters[pid][f];
        });
      });
    }

    function printable() {
      var c = collect(), props = schema.properties.parameters.properties;
      var html = "<h2>Compliance card</h2><dl>" +
        [["Name", c.item.name], ["Type", c.item.type], ["Version", c.item.version],
         ["Submitted by", c.item.submitted_by], ["Date", c.item.date], ["Stage gate", c.stage],
         ["Guideline version", c.guideline_version]]
          .map(function (r) { return "<dt>" + r[0] + "</dt><dd>" + esc(r[1] || "–") + "</dd>"; }).join("") +
        "</dl><table><thead><tr><th>Parameter</th><th>Status</th><th>Justification</th><th>Evidence</th></tr></thead><tbody>" +
        Object.keys(c.parameters).map(function (pid) {
          var p = c.parameters[pid];
          return "<tr><td>" + esc((props[pid] || {}).title || pid) + "</td><td>" + esc(p.status || "") +
                 "</td><td>" + esc(p.justification || "") + "</td><td>" + esc(p.evidence || "") + "</td></tr>";
        }).join("") + "</tbody></table>";
      var box = root.querySelector(".px-print-card") || document.createElement("div");
      box.className = "px-print-card";
      box.innerHTML = html;
      root.appendChild(box);
    }

    stageSel.addEventListener("change", function () { showStage(); save(); });
    form.addEventListener("input", save);
    root.addEventListener("click", function (ev) {
      var btn = ev.target.closest("[data-action]");
      if (!btn) return;
      var action = btn.getAttribute("data-action");
      if (action === "json") {
        var c = collect();
        var name = (c.item.name || "compliance-card").toLowerCase().replace(/[^a-z0-9]+/g, "-");
        download(name + "-" + (c.stage || "card").toLowerCase().replace(/[^a-z0-9]+/g, "-") + ".json",
                 JSON.stringify(c, null, 2) + "\n", "application/json");
      } else if (action === "print") {
        printable();
        window.print();
      } else if (action === "clear") {
        if (!window.confirm("Clear the whole form?")) return;
        form.reset();
        store.del(key);
        showStage();
      }
    });
    window.addEventListener("beforeprint", printable);
    restore();
    showStage();
  }

  function init() {
    document.querySelectorAll("[data-px-checklist]").forEach(checklist);
    document.querySelectorAll("[data-px-riskcheck]").forEach(riskcheck);
    document.querySelectorAll("[data-px-card]").forEach(card);
  }
  if (window.document$) window.document$.subscribe(init);
  else if (document.readyState !== "loading") init();
  else document.addEventListener("DOMContentLoaded", init);
})();
